41	     */
42	    public function parse(array $argv): array
43	    {
44	        $options = ['config' => null, 'output' => null, 'vendor' => null, 'vendorDev' => null, 'coverage' => null, 'serve' => null, 'memoryLimit' => null, 'jobs' => null, 'base' => null, 'head' => null, 'cacheDir' => null, 'noCache' => false, 'clearCache' => false, 'help' => false, 'version' => false];
45	        $count = count($argv);
46	        for ($index = 0; $index < $count; $index++) {
47	            $argument = $argv[$index];
48	            if ($argument === '--help' || $argument === '-h') {
49	                $options['help'] = true;
50	            } elseif ($argument === '--version' || $argument === '-V') {
51	                $options['version'] = true;
52	            } elseif ($argument === '--no-cache') {
53	                $options['noCache'] = true;
54	            } elseif ($argument === '--clear-cache') {
55	                $options['clearCache'] = true;
56	            } elseif ($argument === '--serve') {
57	                $options['serve'] = '127.0.0.1:8090';
58	            } elseif (str_starts_with($argument, '--serve=')) {
59	                $options['serve'] = $this->address(substr($argument, 8));
60	            } elseif ($argument === '--vendor' || str_starts_with($argument, '--vendor=')) {
61	                $options['vendor'] = $this->vendorGlobs($argument, '--vendor');
62	            } elseif ($argument === '--vendor-dev' || str_starts_with($argument, '--vendor-dev=')) {
63	                $options['vendorDev'] = $this->vendorGlobs($argument, '--vendor-dev');
64	            } elseif ($this->isValueOption($argument)) {
65	                $name = $this->optionName($argument);
66	                $options = $this->applyValueOption($options, $name, $this->take($argv, $index, $name));
67	                $index += $this->consumed($argument);
68	            } else {
69	                throw new DocGenException(sprintf('Unknown option: %s', $argument));
70	            }
71	        }
