78	     */
79	    public function isValueOption(string $argument): bool
80	    {
81	        foreach (self::VALUE_OPTIONS as $name) {
82	            if ($argument === '--' . $name || str_starts_with($argument, '--' . $name . '=')) {
83	                return true;
84	            }
85	        }
