109	     */
110	    public function applyValueOption(array $options, string $name, string $value): array
111	    {
112	        if ($name === 'config') {
113	            $options['config'] = $value;
114	        } elseif ($name === 'output') {
115	            $options['output'] = $value;
116	        } elseif ($name === 'coverage') {
117	            $options['coverage'] = $value;
118	        } elseif ($name === 'memory-limit') {
119	            $options['memoryLimit'] = $this->memoryLimit($value);
120	        } elseif ($name === 'jobs') {
121	            $options['jobs'] = $this->jobs($value);
122	        } elseif ($name === 'cache-dir') {
123	            $options['cacheDir'] = $value;
124	        } elseif ($name === 'base') {
125	            $options['base'] = $value;
126	        } elseif ($name === 'head') {
127	            $options['head'] = $value;
128	        } else {
