135	    /**
136	     * Splits a BASE..HEAD range into the two compared revisions.
137	     *
138	     * A range without a head compares against the working tree, which is
139	     * what a reader looking at their own uncommitted change wants.
140	     *
141	     * @param array{config: ?string, output: ?string, vendor: ?list<string>, vendorDev: ?list<string>, coverage: ?string, serve: ?string, memoryLimit: ?string, jobs: ?int, base: ?string, head: ?string, cacheDir: ?string, noCache: bool, clearCache: bool, help: bool, version: bool} $options
142	     *
143	     * @return array{config: ?string, output: ?string, vendor: ?list<string>, vendorDev: ?list<string>, coverage: ?string, serve: ?string, memoryLimit: ?string, jobs: ?int, base: ?string, head: ?string, cacheDir: ?string, noCache: bool, clearCache: bool, help: bool, version: bool}
144	     *
145	     * @throws DocGenException when the range names no base revision
146	     */
147	    public function revisionRange(array $options, string $value): array
148	    {
149	        $parts = explode('..', $value, 2);
150	        $base = trim($parts[0]);
151	        if ($base === '') {
152	            throw new DocGenException(sprintf(
153	                'Invalid --diff range: %s. Use BASE to compare against the working tree, or BASE..HEAD to compare two revisions.',
154	                $value,
155	            ));
156	        }
157	
158	        $head = count($parts) === 2 ? trim($parts[1]) : '';
159	        $options['base'] = $base;
160	        $options['head'] = $head === '' ? $options['head'] : $head;
161	
162	        return $options;
163	    }
164	
165	    /**
166	     * Rejects the option combinations that cannot be acted on.
167	     *
168	     * @param array{config: ?string, output: ?string, vendor: ?list<string>, vendorDev: ?list<string>, coverage: ?string, serve: ?string, memoryLimit: ?string, jobs: ?int, base: ?string, head: ?string, cacheDir: ?string, noCache: bool, clearCache: bool, help: bool, version: bool} $options
169	     *
170	     * @return array{config: ?string, output: ?string, vendor: ?list<string>, vendorDev: ?list<string>, coverage: ?string, serve: ?string, memoryLimit: ?string, jobs: ?int, base: ?string, head: ?string, cacheDir: ?string, noCache: bool, clearCache: bool, help: bool, version: bool}
