172	     * @throws DocGenException when a head revision has nothing to compare against
173	     */
174	    public function validated(array $options): array
175	    {
176	        if ($options['head'] !== null && $options['base'] === null) {
177	            throw new DocGenException('Option --head needs a revision to compare against: add --base=REVISION, or use --diff=BASE..HEAD.');
178	        }
179	
180	        return $options;
181	    }
182	
183	    /**
184	     * Returns the inline value of a long option, or null.
185	     */
186	    public function valueOption(string $argument, string $name): ?string
187	    {
188	        $prefix = '--' . $name . '=';
189	        if (str_starts_with($argument, $prefix)) {
190	            $value = substr($argument, strlen($prefix));
191	
192	            return $value !== '' ? $value : null;
193	        }
194	
195	        return null;
196	    }
197	
198	    /**
199	     * Returns the value of an option at the current position.
200	     *
201	     * @param list<string> $argv
202	     *
203	     * @throws DocGenException when the option has no value
204	     */
205	    public function take(array $argv, int $index, string $name): string
206	    {
207	        $inline = $this->valueOption($argv[$index], $name);
208	        if ($inline !== null) {
209	            return $inline;
210	        }
211	
212	        $next = $argv[$index + 1] ?? null;
213	        if ($next === null || str_starts_with($next, '-')) {
214	            throw new DocGenException(sprintf('Option --%s requires a value.', $name));
215	        }
216	
217	        return $next;
218	    }
219	
220	    /**
221	     * Returns how many extra arguments a value option consumed.
222	     */
223	    public function consumed(string $argument): int
224	    {
225	        return str_contains($argument, '=') ? 0 : 1;
226	    }
227	
228	    /**
229	     * Returns the package name globs of a vendor option.
230	     *
231	     * The bare option without a value means every installed package, so it
232	     * expands to the match-all glob.
233	     *
234	     * @param string $argument the raw argument, such as --vendor-dev=acme/*
235	     * @param string $option the option name, such as --vendor-dev
236	     *
237	     * @return list<string>
238	     *
239	     * @throws DocGenException when the option has a value without any glob
240	     */
241	    public function vendorGlobs(string $argument, string $option): array
242	    {
243	        if ($argument === $option) {
244	            return ['*'];
245	        }
246	
247	        return $this->globList(substr($argument, strlen($option) + 1), $option);
248	    }
249	
250	    /**
251	     * Splits a comma-separated glob list.
252	     *
253	     * @param string $option the option name quoted in the error message
254	     *
255	     * @return list<string>
256	     *
257	     * @throws DocGenException when the list is empty
258	     */
259	    public function globList(string $value, string $option): array
260	    {
261	        $globs = [];
262	        foreach (explode(',', $value) as $glob) {
263	            $trimmed = trim($glob);
264	            if ($trimmed !== '') {
265	                $globs[] = $trimmed;
266	            }
267	        }
268	
269	        if ($globs === []) {
270	            throw new DocGenException(sprintf('Option %s requires at least one package name glob.', $option));
271	        }
272	
273	        return $globs;
274	    }
275	
276	    /**
277	     * Validates a memory limit value such as 512M, 1G, or -1.
278	     *
279	     * @throws DocGenException when the value is malformed
280	     */
281	    public function memoryLimit(string $value): string
282	    {
283	        if (preg_match('/^(-1|\d+[KMG]?)$/i', $value) !== 1) {
284	            throw new DocGenException(sprintf('Invalid --memory-limit value: %s. Use a byte count, a value such as 512M or 1G, or -1 for no limit.', $value));
285	        }
286	
287	        return $value;
288	    }
289	
290	    /**
291	     * Validates a worker count such as 4, or 1 for a sequential run.
292	     *
293	     * @throws DocGenException when the value is not a positive number
294	     */
295	    public function jobs(string $value): int
296	    {
297	        if (preg_match('/^[1-9]\d*$/', $value) !== 1) {
298	            throw new DocGenException(sprintf('Invalid --jobs value: %s. Use a worker count of 1 or more, or leave it out to use the cores of this machine.', $value));
299	        }
300	
301	        return (int) $value;
302	    }
303	
304	    /**
305	     * Normalizes a serve address, accepting a bare port number.
306	     *
307	     * @throws DocGenException when the address is malformed
308	     */
309	    public function address(string $value): string
310	    {
311	        if (preg_match('/^\d+$/', $value) === 1) {
312	            return '127.0.0.1:' . $value;
313	        }
314	
315	        if (preg_match('/^[A-Za-z0-9_.\[\]-]+:\d+$/', $value) === 1) {
316	            return $value;
317	        }
318	
319	        throw new DocGenException(sprintf('Invalid --serve address: %s. Use HOST:PORT or a port number.', $value));
320	    }
321	}
