237	     * @param int $offset where the channel starts, after the leading hash
238	     *
239	     * @return int<0, 255>
240	     */
241	    public function channel(string $hex, int $offset): int
242	    {
243	        return min(255, max(0, (int) hexdec(substr($hex, $offset, 2))));
244	    }
