14	/**
15	 * Renders the site index with the package and layer overviews.
16	 */
17	final class IndexPage
18	{
19	    /** @readonly */
20	    private PageChrome $chrome;
21	
22	    /** @readonly */
23	    private SidebarHtml $sidebar;
24	
25	    /** @readonly */
26	    private GraphSvg $graph;
27	
28	    /**
29	     * Creates an index page renderer from its collaborators.
30	     */
31	    public function __construct(
32	        ?PageChrome $chrome = null,
33	        ?SidebarHtml $sidebar = null,
34	        ?GraphSvg $graph = null,
35	    ) {
36	        $this->chrome = $chrome ?? new PageChrome();
37	        $this->sidebar = $sidebar ?? new SidebarHtml();
38	        $this->graph = $graph ?? new GraphSvg();
39	    }
40	
41	    /**
42	     * Renders the complete site index document.
43	     */
44	    public function render(RenderKit $services): string
45	    {
46	        return $this->chrome->page(
47	            $services,
48	            'index.html',
49	            'Overview',
50	            $this->description($services),
51	            '<span class="crumb-current">Overview</span>',
52	            $this->sidebar->build($services, 'index.html', new SidebarScope(null, null, null, [])),
53	            $this->content($services),
54	        );
55	    }
56	
57	    /**
58	     * Describes the documented project in one sentence.
59	     *
60	     * What a project says about itself in its own manifest describes it
61	     * better than anything countable about the site, so the description of
62	     * the first documented package of the project is preferred.
63	     */
64	    public function description(RenderKit $services): string
65	    {
66	        foreach ($services->model->packages as $package) {
67	            if (!$package->isVendor && $package->manifest->description !== '') {
68	                return $package->manifest->description;
69	            }
70	        }
71	
72	        return sprintf('API documentation of %s.', $services->model->title);
73	    }
74	
75	    /**
76	     * Renders the index content.
77	     */
78	    public function content(RenderKit $services): string
79	    {
80	        $escaper = $services->escaper;
81	        $html = sprintf('<div class="symbol-head"><h1>%s</h1></div>', $escaper->e($services->model->title)) . "\n";
82	        $html .= $this->packageTable($services);
83	        $html .= $this->packageGraph($services);
84	        if ($services->model->warnings !== []) {
85	            $html .= '<details class="notice notice-warn"><summary>Analysis warnings <span class="count">' . count($services->model->warnings) . '</span></summary><ul>';
86	            foreach ($services->model->warnings as $warning) {
87	                $html .= '<li>' . $escaper->e($warning) . '</li>';
88	            }
89	
90	            $html .= '</ul></details>' . "\n";
91	        }
92	
93	        return $html;
94	    }
95	
96	    /**
97	     * Renders the package summary table.
98	     */
99	    public function packageTable(RenderKit $services): string
100	    {
101	        $escaper = $services->escaper;
102	        $counts = [];
103	        foreach ($services->model->classLikes as $classLike) {
104	            if (!$classLike->isDev) {
105	                $counts[$classLike->packageName] = ($counts[$classLike->packageName] ?? 0) + 1;
106	            }
107	        }
108	
109	        $statuses = [];
110	        foreach ($services->model->packages as $package) {
111	            $statuses[] = $services->diff->packageStatus($package->manifest->name);
112	        }
113	
114	        $html = '<section' . $services->diff->combined($statuses)
115	            . '><h2 id="packages">Packages<a class="anchor" href="#packages">§</a></h2><div class="table-wrap"><table class="symbol-table">';
116	        foreach ($services->model->packages as $package) {
117	            $html .= sprintf(
118	                '<tr%s><td><a href="%s">%s</a>%s</td><td class="pkg-count">%d symbols</td><td>%s</td></tr>',
119	                $services->diff->mark($services->diff->packageStatus($package->manifest->name)),
120	                $escaper->e($services->url->packagePage($package->manifest->name)),
121	                $escaper->e($package->manifest->name),
122	                $package->isVendor ? sprintf(' <span class="chip chip-sm chip-ghost">%s</span>', $package->isDevDependency ? 'dev dependency' : 'vendor') : '',
123	                $counts[$package->manifest->name] ?? 0,
124	                $escaper->e($package->manifest->description),
125	            );
126	        }
127	
128	        return $html . '</table></div></section>' . "\n";
129	    }
130	
131	    /**
132	     * Renders the package dependency graph.
133	     */
134	    public function packageGraph(RenderKit $services): string
135	    {
136	        if (count($services->model->packages) < 2) {
137	            return '';
138	        }
139	
140	        $nodes = [];
141	        foreach ($services->model->packages as $package) {
142	            $nodes[] = [
143	                'id' => $package->manifest->name,
144	                'label' => $package->manifest->name,
145	                'href' => $services->url->packagePage($package->manifest->name),
146	                'kind' => $package->isVendor ? 'vendor' : 'pkg',
147	            ];
148	        }
149	
150	        $edges = [];
151	        foreach ($services->model->graph->edges as $edge) {
152	            $edges[] = ['from' => $edge->from, 'to' => $edge->to, 'kind' => $edge->kind];
153	        }
154	
155	        return '<section' . $services->diff->unchanged() . '><h2 id="package-graph">Package Dependencies<a class="anchor" href="#package-graph">§</a></h2>'
156	            . '<div class="graph-wrap">' . $this->graph->render($nodes, $edges) . '</div>'
157	            . '<div class="legend"><span class="legend-item legend-require">require</span><span class="legend-item legend-require-dev">require-dev</span><span class="legend-item legend-suggest">suggest</span></div>'
158	            . '</section>' . "\n";
159	    }
160	}

